(7691094, 1260270, 122678, '<td valign="top">Congratulations!<br/>You are a genius, like no other. The depth of this image blows my mind as to what is photographically conveyable in an image. This is more then a feeling it is a message.  Amazing work.</td>', 'Congratulations!You are a genius, like no other. The depth of this image blows my mind as to what is photographically conveyable in an image. This is more then a feeling it is a message.  Amazing work.', '2021-04-05 09:19:26.000000', NULL, 0),
(7691096, 1260256, 114969, '<td valign="top">Old and generous recipes are the best. You definitely made me hungry: I have a few apples available, baking such pie looks like a good afternoon occupation! Congrats on the ribbon :)</td>', 'Old and generous recipes are the best. You definitely made me hungry: I have a few apples available, baking such pie looks like a good afternoon occupation! Congrats on the ribbon :)', '2021-04-05 10:24:58.000000', NULL, 0),
